async(page)=>{
 const checks=[],base='E:/Dr.RouteFit/prototype/records/2026-10-24-driver-orders/';const assert=(ok,m)=>{if(!ok)throw Error(m)};
 const role=async r=>{await page.locator(`[data-role=${r}]`).first().click();if(r==='dispatch')await page.locator('[data-dispatch-tab=orders]').click()};const open=async a=>page.locator(`[data-action=${a}]`).first().click();
 const fill=async p=>{for(const [k,v]of Object.entries(p)){const el=page.locator(`#action-form [name=${k}]`);if(k==='vehicle'){await page.locator(`[name=vehicle][value=${v}]`).check();continue;}if(typeof v==='boolean')await el.setChecked(v);else if(await el.evaluate(x=>x.tagName)==='SELECT')await el.selectOption(String(v));else await el.fill(String(v))}};
 const submit=async()=>{await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden',timeout:4000})};const act=async(a,p={})=>{await open(a);await fill(p);await submit()};const list=async group=>{await page.locator('[data-driver-tab=orders]').first().click();await page.locator(`[data-driver-group=${group}]`).click()};const state=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')));
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1000});await role('dispatch');await open('qa');await act('reset');await role('dispatch');await act('offer',{vehicle:'V01'});await role('driver');await act('reject',{reason:'DEMO 班次冲突'});await list('cancelled');assert((await page.locator('.driver-order-results').innerText()).includes('司机拒单'),'rejected history missing');await page.locator('.driver-order-results summary').click();assert((await page.locator('.driver-order-results').innerText()).includes('只读'),'history not readonly');assert(!await page.locator('[data-action=accept]').count(),'cancelled history has accept');checks.push('拒单后任务保留只读历史，不误示客户订单已取消');
 await role('dispatch');await page.locator('[data-order="RF-1024-002"]').first().click();await act('edit',{qty:2,payment:'cash',amount:20,commissionPercent:20});const past=new Date(Date.now()+7*3600000-10*60000).toISOString().slice(0,16);await act('promise',{promise:past,basis:'DEMO 已过原承诺的待处理样例',commissionPercent:20,address:true,measured:true,confirmed:true});await act('offer',{vehicle:'V01'});await role('driver');await act('accept');await list('overdue');assert(await page.locator('[data-driver-open="RF-1024-002"]').count()===1,'overdue order missing');await page.setViewportSize({width:390,height:844});assert(await page.locator('[data-driver-group]').count()===4,'four groups missing');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'390px overflow');await page.locator('#driver-order-search').fill('不存在');assert((await page.locator('.driver-order-results').innerText()).includes('暂无匹配'),'search empty missing');await open('driver-clear-search');await page.screenshot({path:base+'overdue-mobile.png',fullPage:true});await page.locator('[data-driver-open="RF-1024-002"]').click();await act('driverIssue',{kind:'address',reason:'DEMO 门口限高，请确认入口'});assert((await page.locator('.driver-issues').innerText()).includes('待调度处理'),'issue not visible');checks.push('四个分类、超时仍可操作、订单搜索、清空和390px布局');
 await page.setViewportSize({width:1440,height:1000});await role('dispatch');await page.locator('[data-dispatch-tab=alerts]').click();assert((await page.locator('main').innerText()).includes('司机上报待处理'),'dispatch alert missing');await page.locator('[data-dispatch-tab=orders]').click();await page.locator('[data-order="RF-1024-002"]').first().click();await act('resolveDriverIssue',{evidence:'DEMO 已电话确认南门可通行，请保留原地址和报价'});await role('driver');assert((await page.locator('.driver-issues').innerText()).includes('南门'),'driver reply missing');await page.screenshot({path:base+'issue-reply.png',fullPage:true});checks.push('司机上报→调度异常队列→记录处理→司机查看回复，履约状态不被自动改写');
 await role('warehouse');await act('prepare',{dimension:true,pattern:true,packaging:true,evidence:'DEMO-LOAD'});await role('driver');await act('pickup',{evidence:'DEMO-HO'});await act('depart');await open('qa');await page.locator('[data-mode=offline]').click();await act('report',{proof:'DEMO-CASH'});await act('deliver',{count:1,receiver:'演示收货人',evidence:'DEMO-POD'});await list('overdue');assert((await page.locator('.driver-order-results').innerText()).includes('证据待同步'),'pending evidence not marked');assert((await state()).orders.find(o=>o.id==='RF-1024-002').status==='in_transit','offline falsely completed');await open('normal');await page.locator('[data-driver-tab=sync]').click();await open('sync');await list('completed');assert(!await page.locator('[data-driver-open="RF-1024-002"]').count(),'partial receipt marked completed');await list('overdue');await page.locator('[data-driver-open="RF-1024-002"]').click();assert((await page.locator('main').innerText()).includes('退回处理中'),'partial return missing');checks.push('离线证据保留重试入口、待同步不冒充完成、部分签收留在未完任务');
 await role('dispatch');await page.locator('[data-order="RF-1024-002"]').first().click();await act('authorizeReturn',{reason:'DEMO 授权余货回仓'});await role('driver');await act('returnArrived');await role('warehouse');await act('receiveReturn',{count:1,evidence:'DEMO-RETURN'});await role('driver');await list('completed');assert((await page.locator('.driver-order-results').innerText()).includes('退回已点收 · 非全部送达'),'return outcome hidden');assert((await page.locator('.driver-order-results').innerText()).includes('账务待处理'),'finance todo hidden');await page.setViewportSize({width:390,height:844});await page.screenshot({path:base+'completed-mobile.png',fullPage:true});await page.reload();await page.locator('[data-driver-tab=orders]').first().click();await page.locator('[data-driver-group=cancelled]').click();assert((await page.locator('.driver-order-results').innerText()).includes('司机拒单'),'history lost on reload');checks.push('仓库点收后转已完成，明确非全部送达与账务待办，取消历史刷新保留');return {status:'PASS',checks};
}
